const ALL_FACETS: readonly RequestFacet[] = ["value", "condition", "callers", "flow"];

function predictedFacets(text: string): Set<RequestFacet> {
  return new Set(extractFacetRequirements(text).map((r) => r.facet));
}

describe("held-out facet set (102 items, EVO-X2 + orchestrator negatives, 2026-09-27)", () => {
  it("every id is unique (data integrity of the embedded table)", () => {
    expect(new Set(HELD_OUT.map((i) => i.id)).size).toBe(HELD_OUT.length);
  });

  const scored = HELD_OUT.filter((item) => item.adjudicated);
  const advisory = HELD_OUT.filter((item) => !item.adjudicated);

  it(`table shape: ${HELD_OUT.length} total, ${scored.length} scored, ${advisory.length} advisory`, () => {
    expect(HELD_OUT.length).toBe(102);
    expect(advisory.length).toBe(2);
  });

  // Per-facet precision/recall over the SCORED (adjudicated:true) subset,
  // multi-label: a positive item's predicted set is compared against its
  // gold set per facet; a negative item contributes to every facet's FP
  // count if it predicts anything at all.
  it("prints and asserts a floor on per-facet precision/recall (reported in FIX-C1's final message)", () => {
    const stats: Record<RequestFacet, { tp: number; fp: number; fn: number }> = {
      value: { tp: 0, fp: 0, fn: 0 },
      condition: { tp: 0, fp: 0, fn: 0 },
      callers: { tp: 0, fp: 0, fn: 0 },
      flow: { tp: 0, fp: 0, fn: 0 },
    };
    let negativeFalsePositiveItems = 0;
    const misses: string[] = [];

    for (const item of scored) {
      const predicted = predictedFacets(item.text);
      const gold = new Set(item.facets);
      if (item.negative) {
        if (predicted.size > 0) negativeFalsePositiveItems += 1;
        for (const facet of ALL_FACETS) if (predicted.has(facet)) stats[facet].fp += 1;
        continue;
      }
      for (const facet of ALL_FACETS) {
        const g = gold.has(facet);
        const p = predicted.has(facet);
        if (g && p) stats[facet].tp += 1;
        else if (g && !p) {
          stats[facet].fn += 1;
          misses.push(`${item.id} [${facet}] "${item.text}"`);
        } else if (!g && p) stats[facet].fp += 1;
      }
    }

    const report: Record<string, { precision: number; recall: number; tp: number; fp: number; fn: number }> = {};
    for (const facet of ALL_FACETS) {
      const { tp, fp, fn } = stats[facet];
      const precision = tp + fp === 0 ? 1 : tp / (tp + fp);
      const recall = tp + fn === 0 ? 1 : tp / (tp + fn);
      report[facet] = { precision, recall, tp, fp, fn };
    }
    // eslint-disable-next-line no-console
    console.log("requestFacets held-out precision/recall:", JSON.stringify(report, null, 2));
    if (misses.length > 0) {
      // eslint-disable-next-line no-console
      console.log("requestFacets held-out misses:", misses.join("\n"));
    }
    const negatives = scored.filter((i) => i.negative).length;
    // eslint-disable-next-line no-console
    console.log(`requestFacets held-out negatives with any false positive: ${negativeFalsePositiveItems}/${negatives}`);

    // Floors are a REGRESSION GUARD (a future edit that tanks recall/precision
    // fails this spec), not a target. OBSERVED on this tree (2026-09-27,
    // after removing the bare "constant(s)"/定数 value trigger — see
    // requestFacets.ts's own comment on that removal): 100% precision AND
    // recall on all four facets (tp/fp/fn = 25/0/0, 23/0/0, 22/0/0, 18/0/0),
    // 0/17 negatives with any false positive. Floors below are set with
    // deliberate headroom under that observed ceiling, not equal to it, so a
    // legitimate future vocabulary refinement is not immediately brittle.
    for (const facet of ALL_FACETS) {
      expect(report[facet]!.recall).toBeGreaterThanOrEqual(0.92);
      expect(report[facet]!.precision).toBeGreaterThanOrEqual(0.85);
    }
    expect(negativeFalsePositiveItems / negatives).toBeLessThanOrEqual(0.15);
  });

  it("advisory (adjudicated:false) items are reported but never asserted on", () => {
    for (const item of advisory) {
      const predicted = [...predictedFacets(item.text)];
      // eslint-disable-next-line no-console
      console.log(`advisory ${item.id}: predicted=[${predicted.join(",")}] gold=[${item.facets.join(",")}]`);
    }
    expect(advisory.length).toBe(2);
  });
});
